WITH sr_ranked AS (SELECT sr.sr_customer_sk, sr.sr_returned_date_sk, sr.sr_net_loss, ROW_NUMBER() OVER (PARTITION BY sr.sr_customer_sk ORDER BY sr.sr_returned_date_sk DESC) AS rn, LAG(sr.sr_net_loss) OVER (PARTITION BY sr.sr_customer_sk ORDER BY sr.sr_returned_date_sk) AS prev_net_loss FROM store_returns sr), web_total AS (SELECT wr.wr_refunded_customer_sk AS customer_sk, SUM(wr.wr_net_loss) AS total_web_net_loss FROM web_returns wr GROUP BY wr.wr_refunded_customer_sk) SELECT c.c_customer_id, c.c_first_name, c.c_last_name, sr.rn, sr.sr_returned_date_sk, sr.sr_net_loss, sr.prev_net_loss, (sr.sr_net_loss - sr.prev_net_loss) AS net_loss_change, CASE WHEN (sr.sr_net_loss - sr.prev_net_loss) > 0 THEN 'Increase' WHEN (sr.sr_net_loss - sr.prev_net_loss) < 0 THEN 'Decrease' ELSE 'No Change' END AS change_indicator, COALESCE(wt.total_web_net_loss,0) AS total_web_net_loss, RANK() OVER (PARTITION BY c.c_customer_sk ORDER BY sr.sr_returned_date_sk DESC) AS recent_return_rank FROM sr_ranked sr JOIN customer c ON sr.sr_customer_sk = c.c_customer_sk LEFT JOIN web_total wt ON wt.customer_sk = c.c_customer_sk WHERE sr.rn <= 5 ORDER BY c.c_customer_id, sr.sr_returned_date_sk DESC
